node -e "
const { spawn } = require('child_process');
const server = spawn('npm', ['run', 'start'], { stdio: ['inherit', 'pipe', 'pipe'] });
let logs = [];
server.stdout.on('data', d => logs.push(d.toString()));
server.stderr.on('data', d => console.log('STDERR:', d.toString()));

setTimeout(async () => {
  const r1 = await fetch('http://localhost:3000/');
  const id1 = r1.headers.get('x-request-id');
  const r2 = await fetch('http://localhost:3000/api/test');
  const id2 = r2.headers.get('x-request-id');
  server.kill();
  console.log('ID1:', id1);
  console.log('ID2:', id2);
  console.log('Unique:', id1 !== id2);
  console.log('Server logs:\n' + logs.join(''));
}, 2000);
"
